export const UI_MESSAGES = { en, ru, es };

export function normalizeLocale(value) {
  const candidate = String(value || '').trim().toLowerCase().split('-')[0];
  return SUPPORTED_LOCALES.includes(candidate) ? candidate : 'en';
}

export function resolveInitialLocale(savedLocale, browserLanguages = []) {
  if (SUPPORTED_LOCALES.includes(String(savedLocale || '').toLowerCase())) return normalizeLocale(savedLocale);
  const languages = Array.isArray(browserLanguages) ? browserLanguages : [browserLanguages];
  for (const language of languages) {
    const candidate = String(language || '').toLowerCase().split('-')[0];
    if (SUPPORTED_LOCALES.includes(candidate)) return candidate;
  }
  return 'en';
}

export function documentLanguage(locale) {
  const normalized = normalizeLocale(locale);
  return normalized === 'es' ? 'es-ES' : normalized;
}

export function t(locale, key, variables = {}) {
  const normalized = normalizeLocale(locale);
  const template = UI_MESSAGES[normalized]?.[key] ?? UI_MESSAGES.en[key] ?? key;
  return String(template).replace(/\{([a-zA-Z0-9_]+)\}/g, (token, name) => (
    Object.prototype.hasOwnProperty.call(variables, name) ? String(variables[name]) : token
  ));
}

export function getDocumentMetadata(locale) {
  return { title: t(locale, 'meta.title'), description: t(locale, 'meta.description') };
}

export function getLocalizedContent(record, locale) {
  const stable = record && typeof record === 'object' ? record : {};
  const english = stable.content?.en || {};
  const selected = stable.content?.[normalizeLocale(locale)] || {};
  return { ...stable, ...english, ...selected };
}
